const num = (v, d = 0) => {
  const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? d : n;
};

const stress = Math.max(0, Math.min(10, num($json.stressLevel)));
const sleep = num($json.sleepHours);
const workload = Math.max(0, Math.min(10, num($json.workload)));
const deadlines = num($json.deadlines);
const feeling = String($json.feeling || '').toLowerCase();

// Weighted stress score
let score = stress;                       // 0-10
score += workload * 0.6;                  // 0-6
score += Math.min(deadlines, 10) * 0.5;   // 0-5
if (sleep < 4) score += 3;
else if (sleep < 6) score += 1.5;

let stressCategory = 'Low';
if (score >= 14) stressCategory = 'High';
else if (score >= 8) stressCategory = 'Moderate';

// Scan the free-text response for signs of being seriously overwhelmed
const distressWords = [
  'overwhelmed', "can't cope", 'cant cope', 'hopeless', 'give up', 'giving up',
  'burnt out', 'burned out', 'burnout', 'panic', 'panicking', 'anxious', 'anxiety',
  'depressed', 'breaking down', 'break down', 'too much', 'exhausted', 'no point',
  'worthless', 'suicidal', 'end it all', "can't go on", 'cant go on'
];
const distressHit = distressWords.some((w) => feeling.includes(w));

const escalate = stressCategory === 'High' || stress >= 9 || distressHit;

return {
  json: {
    ...$json,
    stressLevelNum: stress,
    sleepHoursNum: sleep,
    workloadNum: workload,
    deadlinesNum: deadlines,
    stressScore: Math.round(score * 10) / 10,
    stressCategory,
    distressHit,
    escalate,
  },
};

