={{ (() => {
  const s = $('Assess Stress').item.json;
  const fullName = String(s.name || 'Student').trim();
  const firstName = fullName.split(/\s+/)[0] || 'there';
  const category = String(s.stressCategory || 'Moderate');
  const escalate = s.escalate === true || String(s.escalate).toLowerCase() === 'true';
  const score = Number(s.stressScore ?? 0);
  const maxScore = 24;
  const pct = Math.max(0, Math.min(100, Math.round((score / maxScore) * 100)));
  const stressLevel = Number(s.stressLevelNum ?? s.stressLevel ?? 0);
  const sleep = Number(s.sleepHoursNum ?? s.sleepHours ?? 0);
  const workload = Number(s.workloadNum ?? s.workload ?? 0);
  const deadlines = Number(s.deadlinesNum ?? s.deadlines ?? 0);
  const feeling = String(s.feeling || '').trim();

  const palette = category === 'High'
    ? { color: '#B42318', bg: '#FFF1F3', soft: '#FEE4E2', border: '#FDA29B', glow: 'rgba(217,45,32,0.18)' }
    : category === 'Low'
      ? { color: '#027A48', bg: '#ECFDF3', soft: '#D1FADF', border: '#A6F4C5', glow: 'rgba(18,183,106,0.16)' }
      : { color: '#B54708', bg: '#FFFAEB', soft: '#FEF0C7', border: '#FEDF89', glow: 'rgba(247,144,9,0.16)' };

  const esc = (v) => String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

  const titleCase = (str) => esc(String(str || '').replace(/\b\w/g, c => c.toUpperCase()));

  let summary = '';
  const notes = [];
  if (sleep >= 8) notes.push(`you got a strong <strong>${esc(sleep)} hours</strong> of sleep`);
  else if (sleep >= 6) notes.push(`you got <strong>${esc(sleep)} hours</strong> of sleep`);
  else notes.push(`sleep looks a bit low at <strong>${esc(sleep)} hours</strong>`);

  if (workload >= 8) notes.push(`your workload feels <strong>very high</strong>`);
  else if (workload >= 5) notes.push(`your workload is <strong>moderate to high</strong>`);
  else notes.push(`your workload looks <strong>fairly manageable</strong>`);

  if (deadlines >= 5) notes.push(`you have <strong>${esc(deadlines)} deadlines</strong> stacking up`);
  else if (deadlines > 0) notes.push(`you have <strong>${esc(deadlines)} upcoming deadline${deadlines === 1 ? '' : 's'}</strong>`);
  else notes.push(`you don’t have any urgent deadlines listed`);

  const opening = category === 'High'
    ? 'Today looks intense, so the goal is to reduce pressure and make your next steps feel clearer.'
    : category === 'Moderate'
      ? 'You seem to be carrying a decent amount of pressure, but with a few adjustments you can make today feel more manageable.'
      : 'Things look relatively steady today, so the focus is on keeping your momentum without burning out.';

  summary = `${opening} From your check-in, ${notes.join(', ')}.`;
  if (feeling) summary += ` You also said you feel <strong>“${esc(feeling)}”</strong>.`;

  let advice = String($json.output?.[0]?.content?.[0]?.text || '').trim();
  advice = advice.replace(/^(Hi|Hey|Hello)\s+[^!\n.]+[!.]\s*/i, '');

  const lines = advice.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
  let adviceHtml = '';
  let inList = false;

  for (const rawLine of lines) {
    const numbered = rawLine.match(/^\d+\.\s*(.*)$/);
    const bullet = rawLine.match(/^[-•]\s*(.*)$/);

    if (numbered || bullet) {
      if (!inList) {
        adviceHtml += '<ul style="margin:0;padding:0;list-style:none;">';
        inList = true;
      }
      const content = esc((numbered || bullet)[1]).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
      adviceHtml += '<li style="margin:0 0 12px 0;padding:14px 14px 14px 16px;background:#FFFFFF;border:1px solid #EAECF0;border-left:4px solid ' + palette.color + ';border-radius:12px;line-height:1.6;color:#344054;box-shadow:0 1px 2px rgba(16,24,40,0.04);">'
        + '<span style="display:inline-block;font-weight:700;color:' + palette.color + ';margin-right:8px;">•</span>' + content + '</li>';
    } else {
      if (inList) {
        adviceHtml += '</ul>';
        inList = false;
      }
      const content = esc(rawLine).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
      adviceHtml += '<p style="margin:0 0 12px 0;line-height:1.6;color:#344054;">' + content + '</p>';
    }
  }
  if (inList) adviceHtml += '</ul>';
  if (!adviceHtml) {
    adviceHtml = '<p style="margin:0;line-height:1.6;color:#344054;">Take one manageable step at a time and give yourself space for short breaks.</p>';
  }

  const supportBox = escalate
    ? `<div style="margin-top:22px;padding:18px;background:linear-gradient(135deg,#FFF7ED 0%,#FFF1F3 100%);border:1px solid #FFD6AE;border-radius:16px;box-shadow:0 6px 18px rgba(249,115,22,0.08);">
         <div style="font-size:14px;font-weight:800;color:#B93815;margin-bottom:8px;letter-spacing:0.2px;">Support suggestion</div>
         <div style="font-size:14px;line-height:1.65;color:#7A271A;">
           If today feels like too much, reach out to someone you trust, your study counsellor, or a healthcare professional. Asking for support early is a strength.
         </div>
       </div>`
    : '';

  const meterZoneLabel = category === 'High' ? 'High Zone' : category === 'Low' ? 'Low Zone' : 'Moderate Zone';

  return `
<!doctype html>
<html>
  <body style="margin:0;padding:0;background:#EEF2FF;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;color:#101828;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:linear-gradient(180deg,#EEF2FF 0%,#F8FAFC 100%);padding:26px 12px;">
      <tr>
        <td align="center">
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="max-width:680px;background:#FFFFFF;border:1px solid #E4E7EC;border-radius:24px;overflow:hidden;box-shadow:0 20px 45px rgba(16,24,40,0.10);">
            <tr>
              <td style="padding:0;background:linear-gradient(135deg,#111827 0%,#4338CA 55%,#7C3AED 100%);">
                <div style="padding:28px 30px 30px 30px;">
                  <div style="display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(255,255,255,0.14);font-size:11px;font-weight:700;letter-spacing:0.8px;text-transform:uppercase;color:#E0EAFF;margin-bottom:14px;">Student well-being check-in</div>
                  <div style="font-size:28px;font-weight:800;letter-spacing:-0.4px;color:#FFFFFF;">AI Study Stress Coach</div>
                  <div style="margin-top:8px;font-size:14px;line-height:1.55;color:#D6E4FF;max-width:470px;">A clearer snapshot of today’s pressure level, plus practical next steps to help you regain focus.</div>
                </div>
              </td>
            </tr>

            <tr>
              <td style="padding:28px 30px 8px 30px;">
                <p style="margin:0 0 6px 0;font-size:22px;font-weight:800;color:#101828;">Hi ${esc(firstName)} 👋</p>
                <p style="margin:0 0 22px 0;font-size:14px;line-height:1.7;color:#475467;">Here’s your polished stress snapshot for today — short, visual, and easy to act on.</p>
              </td>
            </tr>

            <tr>
              <td style="padding:0 30px 10px 30px;">
                <div style="background:linear-gradient(180deg,#FCFCFD 0%,#F8FAFC 100%);border:1px solid #EAECF0;border-radius:20px;padding:22px;box-shadow:0 10px 30px ${palette.glow};">
                  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
                    <tr>
                      <td style="vertical-align:top;padding-right:16px;">
                        <div style="font-size:12px;font-weight:800;letter-spacing:0.8px;text-transform:uppercase;color:#667085;margin-bottom:10px;">Stress meter</div>
                        <div style="display:inline-block;padding:8px 13px;border-radius:999px;background:${palette.bg};border:1px solid ${palette.border};color:${palette.color};font-size:14px;font-weight:800;">${esc(category)}</div>
                        <div style="margin-top:14px;font-size:34px;font-weight:800;letter-spacing:-1px;color:#101828;">${esc(score.toFixed ? score.toFixed(1) : score)}<span style="font-size:16px;color:#667085;"> / ${maxScore}</span></div>
                        <div style="margin-top:6px;font-size:13px;color:#667085;">Current zone: <strong style="color:${palette.color};">${meterZoneLabel}</strong></div>
                      </td>
                    </tr>
                  </table>

                  <div style="margin-top:18px;position:relative;">
                    <div style="height:14px;border-radius:999px;background:linear-gradient(90deg,#12B76A 0%,#F79009 50%,#F04438 100%);"></div>
                    <div style="position:relative;height:0;">
                      <div style="position:relative;left:calc(${pct}% - 12px);top:-19px;width:24px;height:24px;border-radius:999px;background:#FFFFFF;border:4px solid ${palette.color};box-shadow:0 8px 18px ${palette.glow};"></div>
                    </div>
                    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin-top:6px;">
                      <tr>
                        <td align="left" style="font-size:11px;color:#667085;">Low</td>
                        <td align="center" style="font-size:11px;color:#667085;">Moderate</td>
                        <td align="right" style="font-size:11px;color:#667085;">High</td>
                      </tr>
                    </table>
                  </div>
                </div>
              </td>
            </tr>

            <tr>
              <td style="padding:10px 30px 10px 30px;">
                <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
                  <tr>
                    <td width="33.33%" style="padding:6px 6px 6px 0;">
                      <div style="background:#F8FAFC;border:1px solid #EAECF0;border-radius:16px;padding:16px;text-align:center;">
                        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.8px;color:#667085;font-weight:800;">Sleep</div>
                        <div style="margin-top:8px;font-size:24px;font-weight:800;color:#101828;">${esc(sleep)}</div>
                        <div style="font-size:12px;color:#667085;">hours</div>
                      </div>
                    </td>
                    <td width="33.33%" style="padding:6px;">
                      <div style="background:#F8FAFC;border:1px solid #EAECF0;border-radius:16px;padding:16px;text-align:center;">
                        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.8px;color:#667085;font-weight:800;">Workload</div>
                        <div style="margin-top:8px;font-size:24px;font-weight:800;color:#101828;">${esc(workload)}</div>
                        <div style="font-size:12px;color:#667085;">out of 10</div>
                      </div>
                    </td>
                    <td width="33.33%" style="padding:6px 0 6px 6px;">
                      <div style="background:#F8FAFC;border:1px solid #EAECF0;border-radius:16px;padding:16px;text-align:center;">
                        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.8px;color:#667085;font-weight:800;">Deadlines</div>
                        <div style="margin-top:8px;font-size:24px;font-weight:800;color:#101828;">${esc(deadlines)}</div>
                        <div style="font-size:12px;color:#667085;">upcoming</div>
                      </div>
                    </td>
                  </tr>
                </table>
              </td>
            </tr>

            <tr>
              <td style="padding:12px 30px 6px 30px;">
                <div style="background:#FFFFFF;border:1px solid #EAECF0;border-radius:18px;padding:20px;">
                  <div style="font-size:14px;font-weight:800;color:#101828;margin-bottom:10px;">Today at a glance</div>
                  <p style="margin:0;font-size:14px;line-height:1.75;color:#475467;">${summary}</p>
                </div>
              </td>
            </tr>

            <tr>
              <td style="padding:14px 30px 6px 30px;">
                <div style="font-size:18px;font-weight:800;color:#101828;margin-bottom:12px;">Your recommendations</div>
                ${adviceHtml}
                ${supportBox}
              </td>
            </tr>

            <tr>
              <td style="padding:20px 30px 28px 30px;">
                <div style="padding-top:18px;border-top:1px solid #EAECF0;">
                  <p style="margin:0 0 4px 0;font-size:14px;font-weight:700;color:#101828;">You’ve got this.</p>
                  <p style="margin:0;font-size:14px;color:#667085;">The AI Study Stress Coach</p>
                </div>
              </td>
            </tr>

            <tr>
              <td style="padding:16px 30px 20px 30px;background:#F9FAFB;border-top:1px solid #EAECF0;">
                <p style="margin:0;font-size:11px;line-height:1.65;color:#98A2B3;">AI Study Stress Coach is a well-being support tool created for SDG 3: Good Health &amp; Well-being. It provides general support and is not medical advice, a diagnosis, or a replacement for professional help.</p>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
})() }}
